import{g as s}from"./index-CwGB5E4O.js";const r={async getAll(){return(await s.get("/rentals")).data},async getById(e){return(await s.get(`/rentals/${e}`)).data},async getActive(){return(await s.get("/rentals/active")).data},async getCompleted(){return(await s.get("/rentals/completed")).data},async getOverdue(){return(await s.get("/rentals/overdue")).data},async issue(e){return(await s.post("/rentals/issue",e)).data},async return(e){return(await s.post("/rentals/return",e)).data},async extend(e,t){return(await s.put(`/rentals/${e}`,t)).data},async cancel(e){return(await s.delete(`/rentals/${e}`)).data},async getEquipmentHistory(e){return(await s.get(`/rentals/equipment/${e}`)).data}};export{r};
